"""Write COMPARISON.md from results/run.json. Every number in it comes from the run."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def main():
    r = json.loads((ROOT / "results" / "run.json").read_text())
    a, ap, b, rc = r["path_a"], r["path_a_prime"], r["path_b"], r["router"]

    def row(label, f):
        return f"| {label} | {f(a)} | {f(ap)} | {f(b)} |"

    lines = [
        "# Comparison: the same agent task, three ways",
        "",
        "Generated by `scripts/report.py` from `results/run.json`. Task: for campaign Acme Q4, find the worst and best cost per conversion, "
        "propose moving $5,000, and name the account owner. Token figures are estimates (characters ÷ 4, the estimate the Apollo MCP Server "
        "prints for its own tools); use them to compare paths, not to price anything.",
        "",
        f"All three paths reached the same decision: **{r['same_decision']}** "
        f"({b['decision']['reason']}; move ${b['decision']['amount']:,.0f} from {b['decision']['from']} to {b['decision']['to']}; notify {b['decision']['owner']}).",
        "",
        "| | A: one tool per REST endpoint | A′: purpose-built tools | B: Apollo (Connectors, router, MCP Server) |",
        "|---|---|---|---|",
        row("Tools the model sees", lambda p: f"{len(p['tools'])} (~{p['est_tokens_tool_definitions']} tokens of definitions)"),
        row("MCP calls for the task", lambda p: p["task"]["mcp_calls"]),
        row("Returned to the model", lambda p: f"{p['task']['chars_returned']:,} chars (~{p['task']['est_tokens_returned']:,} tokens)"),
        row("REST calls behind it", lambda p: p["task"]["rest_calls"]["total"]),
        row("PII values that reached the model", lambda p: len(p["task"]["pii_reaching_model"])),
        "| Unapproved budget write by the agent | "
        f"{a['unapproved_write']} (`set_budget` is a tool) | no tool for it | no tool for it; agent token checked at the router below |",
        f"| Ad-hoc query by the agent | n/a | n/a | {b['adhoc_query']} (`{b['adhoc_response'][:60]}`) |",
        "",
        "**Reading it.** A′ matches B on what reaches the model, because a person wrote three tools for this one task and filtered the fields by hand. "
        "B's REST call count is one higher than A's because the graph fetches the campaign again for `AccountOwner`. "
        "The difference between A′ and B is where the rules live. In A′ they are in one server's Python, for one agent. "
        "In B the joins are in the schema, the field rules are `@requiresScopes` in the schema, and the router enforces them for every client, "
        "including one that skips the MCP server and calls the graph directly with the same token.",
        "",
        "## The agent's token at the router (scenarios 4 and 5)",
        "",
    ]
    if "skipped" in rc:
        lines.append(f"Not run: {rc['skipped']}")
    else:
        for who in ("agent", "human"):
            x = rc[who]
            lines += [f"**{who} token**", "", "```json", json.dumps({"pii_query": x["pii_query"], "apply": x["apply"],
                      "apply_reached_ads_service": x["apply_reached_ads_service"]}, indent=2), "```", ""]
    ks = r.get("kill_switch")
    if ks:
        lines += ["## Kill switch (scenario 7)", "",
                  f"Tools before: {', '.join(ks['before'])}. With `ProposeBudgetMove.graphql` removed: {', '.join(ks['during'])} "
                  f"({ks['seconds_to_remove']} s to drop). Restored: {', '.join(ks['after'])} ({ks['seconds_to_restore']} s). "
                  "The MCP server was not restarted.", ""]
    exp = r.get("expectations") or []
    if exp:
        lines += ["## Expectations", "", "Every claim the README makes, checked against this run.", "",
                  "| Claim | Result |", "|---|---|"]
        lines += [f"| {e['claim']} | {'pass' if e['pass'] else '**FAIL**'} |" for e in exp]
        lines.append("")
    lines += ["## Raw", "", "Full output: [results/run.json](results/run.json)."]
    (ROOT / "COMPARISON.md").write_text("\n".join(lines) + "\n")
    print("wrote COMPARISON.md")


if __name__ == "__main__":
    main()
